using Microsoft.EntityFrameworkCore;
using System.Text.Json.Nodes;
namespace Society.Api;
public static class CommunityIntelligence {
 public static void Map(RouteGroupBuilder api){var t=api.MapGroup("/societies/{tenant:guid}/community").RequireAuthorization();
 t.MapGet("/members/{id:guid}/activity",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s,MembershipService ms)=>{var directory=await ms.Directory(tenant);var member=await directory.SingleOrDefaultAsync(m=>m.Id==id)??throw new AccessDeniedException();var user=await db.Persons.Where(p=>p.Id==member.PersonId).Select(p=>p.UserId).SingleAsync();return await s.Posts(tenant).Where(p=>p.AuthorId==user&&p.Status=="Published").OrderByDescending(p=>p.PublishedAt).Take(30).Select(p=>new{p.Id,p.Title,p.PublishedAt,p.Achievement}).ToListAsync();});
 t.MapGet("/intelligence",CommunityMetrics.Read);
 t.MapGet("/chapters/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s,MembershipService ms)=>{await a.Member(tenant);var unit=await db.Units.SingleOrDefaultAsync(u=>u.TenantId==tenant&&u.Id==id)??throw new AccessDeniedException();var directory=await ms.Directory(tenant);if(!await s.Mine(tenant).AnyAsync(m=>m.ChapterId==id)&&!await a.Can(tenant,"activities.read",id)&&!await directory.AnyAsync(m=>m.ChapterId==id))throw new AccessDeniedException();var details=MembershipService.Json(unit.Details);var ancestors=await MembershipService.Ancestors(db,tenant,id);var region=await db.Units.Where(u=>u.TenantId==tenant&&ancestors.Contains(u.Id)&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Region")).Select(u=>u.Name).FirstOrDefaultAsync();var posts=s.Posts(tenant).Where(p=>p.UnitId==id&&p.Status=="Published");var now=DateTimeOffset.UtcNow;return Results.Ok(new{unit.Id,unit.Name,unit.Code,unit.Status,formation=details["formationDate"]?.ToString(),city=details["city"]?.ToString(),logo=details["logoUrl"]?.ToString(),cover=details["coverUrl"]?.ToString(),region,members=await directory.CountAsync(m=>m.ChapterId==id),achievements=await posts.CountAsync(p=>p.Achievement),completedPrograms=await s.Events(tenant).CountAsync(e=>e.UnitId==id&&e.Status=="Published"&&e.EndsAt<now),leadership=await (from ap in db.OfficerAppointments join pos in db.OfficerPositions on ap.PositionId equals pos.Id join m in directory on ap.MembershipId equals m.Id join p in db.Persons on m.PersonId equals p.Id where ap.TenantId==tenant&&ap.UnitId==id&&ap.Status=="Approved"&&ap.StartsAt<=now&&ap.EndsAt>now select new{position=pos.Name,name=p.FullName,ap.EndsAt}).Take(50).ToListAsync(),gallery=await db.Set<CommunityMedia>().Where(m=>m.TenantId==tenant&&m.ResourceKind=="Post"&&m.ContentType=="image/png"&&posts.Any(p=>p.Id==m.ResourceId)).OrderByDescending(m=>m.Id).Take(30).Select(m=>new{m.Id,m.Name,m.ResourceId}).ToListAsync()});});
 }
}
